def _mint_urn(aid, wid):
    return f"urn:cts:greekLit:tlg{aid}.tlg{wid}"


def _as_source_list(value):
    """Normalise an AUTHOR-level `source` to a list of strings.

    A bare string would be shredded into a char array by list(), e.g.
    list("local:curated") -> ['l','o','c',...] — which still satisfies the
    schema ({type:array,items:string,minItems:1}), so validation could not
    catch it. Accept both spellings; default to the curated tier.
    """
    if not value:
        return ["local:curated"]
    if isinstance(value, str):
        return [value]
    return list(value)

